'use strict';
const BASE_PATH = '/energy-md';
function localPath(path) { return path === BASE_PATH ? '/' : path.startsWith(BASE_PATH + '/') ? path.slice(BASE_PATH.length) : path; }

const UI_LANG = window.ENERGY_LANG || 'ru';
let DATASETS;
let DATA, saved = new Set(), filtered = [];
const searchKey = value => String(value).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase();
const $ = (q, root = document) => root.querySelector(q);
const $$ = (q, root = document) => [...root.querySelectorAll(q)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num = (n, digits = 0) => Number(n).toLocaleString(UI_LANG==='ro'?'ro-RO':'ru-RU', {maximumFractionDigits:digits,minimumFractionDigits:digits});
const money = n => num(n / 1000000, 2) + ' mil. MDL';
const priority = {A:'Verificare prioritară',B:'Date de clarificat',S:'Grupuri mari'};
const getCompany = id => DATA.companies.find(c => c.id === id);
const getSector = name => DATA.sectors.find(s => s.name === name);
const route = localPath(location.pathname).replace(/\/+$/, '') || '/';
const params = new URLSearchParams(location.search);
const sectorUrl = s => '/energy-md/sector/' + s.id + '/';
const companyUrl = c => '/energy-md/company/' + c.id + '/';
const links = raw => [...new Set(String(raw ?? '').match(/https?:\/\/[^\s<>";]+/g) || [])].map(s=>s.replace(/[),]+$/,''));
const sourceLinks = raw => `<div class="source-links">${links(raw).map(u => {let label; try{label=new URL(u).hostname.replace(/^www\./,'');}catch{return '';}return `<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;}).join('')}</div>`;
function toast(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),3000);}
async function copyText(value){try{await navigator.clipboard.writeText(value);toast('Copiat. Puteți lipi textul în căutare sau în chat.');return true;}catch{const t=document.createElement('textarea');t.value=value;t.style.position='fixed';t.style.top='-9999px';document.body.append(t);t.select();let ok=false;try{ok=document.execCommand('copy');}catch{}t.remove();toast(ok?'Text copiat.':'Copierea nu a reușit. Selectați manual textul din câmp.');return ok;}}
function loadSaved(){try{const a=JSON.parse(localStorage.getItem('energy-md-saved')||'[]');if(Array.isArray(a))saved=new Set(a.filter(id=>DATA.companies.some(c=>c.id===id)));}catch{saved=new Set();}}
function saveButton(c){return `<button class="save ${saved.has(c.id)?'saved':''}" data-save="${c.id}" aria-label="${saved.has(c.id)?'Eliminați din favorite':'Adăugați la favorite'}: ${esc(c.name)}" aria-pressed="${saved.has(c.id)}" title="Favorite pe acest dispozitiv">${saved.has(c.id)?'★':'☆'}</button>`;}
function pageHead(title,desc='',parent=''){return `<div class="page-head"><div class="breadcrumb"><a href="/energy-md/">Acasă</a><span>/</span>${parent?parent+'<span>/</span>':''}<span>${esc(title)}</span></div><h1>${esc(title)}</h1>${desc?`<p>${desc}</p>`:''}</div>`;}
function notice(){return '<div class="note-strip"><strong>Pragul de selecție: de la 30 000 MDL pe lună.</strong> Cheltuielile companiilor nu sunt încă confirmate prin facturi. Veniturile, utilajele și procesele justifică verificarea, dar nu reprezintă consum măsurat.</div>';}
function companyCard(c,rank=false){return `<article class="company-card"><div class="card-top"><div>${rank?`<span class="wave-rank">${String(c.wave.rank).padStart(2,'0')} / </span>`:''}<span class="tag ${c.priority}" title="${priority[c.priority]}">${c.priority} · ${priority[c.priority]}</span></div>${saveButton(c)}</div><h3><a href="${companyUrl(c)}">${esc(c.name)}</a></h3><a class="sector-label" href="${sectorUrl(getSector(c.sector))}">${esc(c.sector)} ↗</a><p class="fact">${esc(c.facts)}</p><div class="card-meta">${dayBadge(c)}${c.finance?`<span class="tag">${money(c.finance.revenue)} · ${c.finance.year}</span>`:'<span class="tag">Venituri neprecizate</span>'}${c.wave&&!rank?'<span class="tag orange">Selecția inițială</span>':''}</div><div class="card-bottom"><a href="${companyUrl(c)}">Analiza companiei ↗</a><button class="copy-small" data-copy-question="${c.id}" title="Copiați întrebarea de calificare">Copiați întrebarea</button></div></article>`;}
function sectorTile(s,i=0){return `<a class="sector-tile" href="${sectorUrl(s)}"><div class="sector-top"><span>${String(i+1).padStart(2,'0')} / SECTOR</span><span>↗</span></div><h3>${esc(s.name)}</h3><p>${s.count} ${s.count===1?'profil':s.count<5?'profiluri':'profiluri'} în studiu</p><div class="track"><span style="width:${s.count*10}%"></span></div></a>`;}
function home(){const tops=[...DATA.sectors].sort((a,b)=>b.count-a.count).slice(0,6);return `<section class="hero"><div><div class="eyebrow">Republica Moldova · studiu din 17.10.2026</div><h1>Găsiți companii<br>pentru care contează<br><em>prețul energiei.</em></h1><p class="hero-description">Căutăm întreprinderi cu sarcină electrică diurnă. Producția, programele publicate și volumele lunare reale ajută la alegerea următorului client.</p><div class="actions"><a class="button" href="/energy-md/catalog/">Selectați companii <span>↗</span></a><a class="button secondary" href="/energy-md/research/">Creați o interogare <span>+</span></a></div><p class="small-note">Pentru întreprinderi și organizații. Prioritate principală: activitatea de zi.</p></div><div class="hero-board"><div class="board-grid"></div><div class="board-top"><span><i class="live-dot"></i> CRITERIU DE SELECȚIE</span><span>MD / 2026</span></div><div class="threshold"><div class="number">30 000<span style="font-size:.4em">+</span></div><div class="unit"><span>MDL pentru electricitate pe lună</span><span>NU PUTERE ÎN kW</span></div></div><p class="board-caption">Căutăm motive pentru verificare:<br>producție în timpul zilei,<br>utilaje și amploarea activității.</p><div class="load-bars" aria-hidden="true">${[24,40,34,58,43,65,52,75,61,88,74,100,85,92,78,95].map(v=>`<i style="height:${v}%"></i>`).join('')}</div><div class="board-foot"><span>SCHEMĂ · NU DATE DE CONSUM</span><span>↗</span></div></div></section><section class="stats" aria-label="Dimensiunea bazei"><div class="stat"><strong>${DATA.companies.length}</strong><span>companii<br>și grupuri</span></div><div class="stat"><strong>${DATA.sectors.length}</strong><span>sectoare<br>de activitate</span></div><div class="stat"><strong>25</strong><span>înregistrări<br>cu venituri</span></div><div class="stat"><strong>${dayCandidates().length}</strong><span>programe<br>diurne publicate</span></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">01 / Harta căutării</div><h2>Sectoare în care merită<br>verificată sarcina electrică</h2></div><a class="text-link" href="/energy-md/sectors/">Toate ${DATA.sectors.length} sectoare ↗</a></div><div class="sector-grid">${tops.map(sectorTile).join('')}</div></section><section class="dark-section"><div><div class="eyebrow">02 / De la indiciu la decizie</div><h2>Veniturile justifică<br>o întrebare.<br>Profilul diurn este<br>baza selecției.</h2><p>Baza nu conține încă cheltuieli confirmate peste prag. Fiecare etapă clarifică dacă întreprinderea este potrivită pentru compararea condițiilor de furnizare.</p><a class="button secondary" style="color:white;border-color:#ffffff55" href="/energy-md/method/">Cum funcționează selecția ↗</a></div><div class="steps"><div class="step"><span>01</span><div><h3>Identificați un indiciu de producție</h3><p>Camere frigorifice, utilaje, extrudare, pompe, mai multe schimburi.</p></div></div><div class="step"><span>02</span><div><h3>Verificați amploarea și unitatea</h3><p>Venituri, utilaje în funcțiune, adresa unității și persoana juridică plătitoare.</p></div></div><div class="step"><span>03</span><div><h3>Confirmați achizițiile din rețea</h3><p>Facturi reale, sezonalitate și consumul rămas după producția proprie.</p></div></div><div class="step"><span>04</span><div><h3>Comparați condițiile de furnizare</h3><p>Același volum, componente ale prețului și condiții contractuale. Economiile trebuie calculate.</p></div></div></div></section><section class="section"><div class="section-head"><div><div class="eyebrow">03 / Începeți concret</div><h2>Prioritate diurnă</h2></div><a class="text-link" href="/energy-md/wave/">${dayCandidates().length} programe diurne ↗</a></div><div class="company-grid">${dayCandidates().slice(0,3).map(c=>companyCard(c)).join('')}</div><div class="callout"><div><h3>Următoarea întrebare este pregătită.</h3><p>Creați o interogare pentru companie sau sector, precizați sarcina și copiați textul pentru a continua căutarea.</p></div><a class="button" href="/energy-md/research/">Deschideți generatorul ↗</a></div></section>`;}
function catalog(){return pageHead('Companii de la care merită să începeți',`${DATA.companies.length} profiluri. Prioritate: achiziții diurne din rețea de la 30 000 MDL/lună. Filtrul arată nivelul de confirmare a programului, nu ponderea diurnă măsurată.`)+`<div class="content"><div class="filters"><div class="field"><label for="q">Căutare în bază</label><input type="search" id="q" placeholder="Companie, oraș, proces, IDNO…" autocomplete="off"></div><div class="field"><label for="sector-filter">Sector</label><select id="sector-filter"><option value="">Toate ${DATA.sectors.length} de activitate</option>${DATA.sectors.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label for="priority-filter">Prioritate</label><select id="priority-filter"><option value="">Toate prioritățile</option><option value="A">A · prioritate</option><option value="B">B · clarificare</option><option value="S">S · grupuri</option></select></div><div class="field"><label for="day-filter">Profil diurn</label><select id="day-filter"><option value="">Toate stările</option><option value="signal">Există un program publicat</option>${Object.entries(DATA.dayLabels).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('')}</select></div><div class="field"><label for="sort-filter">Sortare</label><select id="sort-filter"><option value="day">Mai întâi indiciile diurne</option><option value="id">Ordinea din bază</option><option value="name">După denumire</option><option value="revenue">După venituri ↓</option><option value="wave">Selecția inițială</option></select></div><div class="filter-bottom"><label class="check"><input type="checkbox" id="finance-only">Cu date despre venituri</label><label class="check"><input type="checkbox" id="wave-only">Selecția inițială</label><label class="check"><input type="checkbox" id="saved-only">Favorite</label><button class="reset" id="reset-filters">Resetați filtrele</button></div></div><div class="legend"><span>A — calificare prioritară</span><span>B — clarificați amploarea / datele</span><span>S — abordare separată pentru grup</span></div><div class="results-bar"><span id="result-count" aria-live="polite"></span><button class="button secondary small" id="export-csv">Descărcați selecția CSV ↓</button></div><div id="company-results" class="company-grid"></div>${notice()}<p class="small-note">Steluța salvează favoritele în acest browser. Veniturile se referă la ani diferiți și nu reprezintă cheltuieli pentru electricitate. Exportul include selecția curentă și sursele.</p></div>`;}
function initCatalog(){const controls=['q','sector-filter','priority-filter','day-filter','sort-filter','finance-only','wave-only','saved-only'];$('#q').value=params.get('q')||'';$('#sector-filter').value=params.get('sector')||'';$('#priority-filter').value=params.get('priority')||'';$('#day-filter').value=params.get('day')||'';$('#sort-filter').value=params.get('sort')||'day';$('#wave-only').checked=params.get('wave')==='1';$('#finance-only').checked=params.get('finance')==='1';$('#saved-only').checked=params.get('saved')==='1';controls.forEach(id=>$('#'+id).addEventListener(id==='q'?'input':'change',filterCatalog));$('#reset-filters').addEventListener('click',()=>{controls.forEach(id=>{const e=$('#'+id);if(e.type==='checkbox')e.checked=false;else e.value=id==='sort-filter'?'day':'';});filterCatalog();});$('#export-csv').addEventListener('click',exportCSV);filterCatalog();}
function filterCatalog(){const q=searchKey($('#q').value.trim());const sector=DATA.sectors.find(s=>s.id===$('#sector-filter').value)?.name;const p=$('#priority-filter').value;filtered=DATA.companies.filter(c=>(!q||searchKey([c.id,c.name,c.sector,c.location,c.facts,c.inference,c.finance?.idno,c.idno,c.day.hours,c.day.evidence,...Object.values((DATASETS?.[UI_LANG==='ro'?'ru':'ro']?.companies.find(x=>x.id===c.id))||{})].join(' ')).includes(q))&&(!$('#day-filter').value||($('#day-filter').value==='signal'?['factory','shift','general'].includes(c.day.kind):c.day.kind===$('#day-filter').value))&&(!sector||c.sector===sector)&&(!p||c.priority===p)&&(!$('#finance-only').checked||c.finance)&&(!$('#wave-only').checked||c.wave)&&(!$('#saved-only').checked||saved.has(c.id)));const sort=$('#sort-filter').value;filtered.sort(sort==='day'?(a,b)=>dayOrder[a.day.kind]-dayOrder[b.day.kind]:sort==='name'?(a,b)=>a.name.localeCompare(b.name,UI_LANG):sort==='revenue'?(a,b)=>(b.finance?.revenue||-1)-(a.finance?.revenue||-1):sort==='wave'?(a,b)=>(a.wave?.rank||999)-(b.wave?.rank||999):(a,b)=>a.id.localeCompare(b.id));$('#result-count').innerHTML=`Găsite <strong>${filtered.length}</strong> din ${DATA.companies.length} profiluri`;$('#export-csv').disabled=!filtered.length;$('#company-results').innerHTML=filtered.length?filtered.map(c=>companyCard(c)).join(''):'<div class="empty"><h3>Nu există companii în această selecție</h3><p>Eliminați unele filtre sau modificați expresia de căutare.</p><button class="button secondary" data-reset>Resetați filtrele</button></div>';const pms=new URLSearchParams({lang:UI_LANG});if(q)pms.set('q',$('#q').value.trim());if(sector)pms.set('sector',$('#sector-filter').value);if(p)pms.set('priority',p);if($('#day-filter').value)pms.set('day',$('#day-filter').value);if(sort!=='day')pms.set('sort',sort);if($('#finance-only').checked)pms.set('finance','1');if($('#wave-only').checked)pms.set('wave','1');if($('#saved-only').checked)pms.set('saved','1');history.replaceState(null,'',location.pathname+(pms.size?'?'+pms:''));}
function exportCSV(){const rows=[['ID','Companie','Sector','Prioritate','Adresă / localizare','Informații publicate','Concluzie analitică','Întrebare de verificare','Telefon','Email / formular','Destinația contactului','Persoana de solicitat','Venituri MDL','An','IDNO','Sursa activității','Sursa contactului','Sursa financiară','Cheltuieli pentru electricitate','Starea profilului diurn','Ore publicate','Baza programului','Sursa programului'],...filtered.map(c=>[c.id,c.name,c.sector,c.priority,c.location,c.facts,c.inference,c.question,c.contact.phone,c.contact.email,c.contact.quality,c.contact.person,c.finance?.revenue??'',c.finance?.year??'',c.idno||c.finance?.idno||'',c.sources,c.contact.sources,c.finance?.sources??'','Neconfirmat',c.day.label,c.day.hours,c.day.evidence,c.day.sources])];const cell=v=>{let s=String(v??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='Energy-Selection.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);toast('Selecție exportată: '+filtered.length+' profiluri.');}
function sectors(){return pageHead(`${DATA.sectors.length} sectoare. Un singur criteriu.`,'Extindem căutarea prin procese care pot genera sarcină electrică regulată. Numărul profilurilor reflectă acest eșantion, nu dimensiunea sectorului.')+`<div class="content"><div class="sector-grid">${DATA.sectors.map(sectorTile).join('')}</div>${notice()}</div>`;}
function sectorPage(s){const items=DATA.companies.filter(c=>c.sector===s.name);return pageHead(s.name,'Întreprinderile sectorului, informațiile publicate și întrebările pentru continuarea cercetării.','<a href="/energy-md/sectors/">Sectoare</a>')+`<div class="content"><div class="sector-intro"><div><div class="panel"><span class="label inference">CONCLUZIE · LOGICA SELECȚIEI</span><h2>Verificăm procesul și amploarea sa</h2><p>${esc(items[0].inference)}</p><p class="small-note">Acest argument provine din profilul ${esc(items[0].name)}. Pentru celelalte întreprinderi sunt necesare propriile date despre utilizare și utilaje.</p><div class="actions"><a class="button" href="/energy-md/research/?sector=${s.id}">Interogare pentru sector ↗</a><a class="button secondary" href="/energy-md/catalog/?sector=${s.id}">Filtrați companiile</a></div></div></div><div class="sector-stat"><span class="eyebrow">ÎN ACEASTĂ SELECȚIE</span><strong>${items.length}</strong><p>profiluri de companii și grupuri</p><div class="data-list"><div><dt>Prioritate A</dt><dd>${items.filter(c=>c.priority==='A').length}</dd></div><div><dt>Selecția inițială</dt><dd>${items.filter(c=>c.wave).length}</dd></div><div><dt>Cu venituri publicate</dt><dd>${items.filter(c=>c.finance).length}</dd></div></div></div></div><div class="company-grid">${items.map(c=>companyCard(c)).join('')}</div>${notice()}</div>`;}
function wave(){return dayWave();}
function companyPage(c){const f=c.finance;const con=c.contact;return pageHead(c.name,esc(c.location),'<a href="/energy-md/catalog/">Companii</a>')+`<div class="content"><div class="subtitle-line"><span class="tag">${c.id}</span><span class="tag ${c.priority}">${c.priority} · ${priority[c.priority]}</span><a class="tag" href="${sectorUrl(getSector(c.sector))}">${esc(c.sector)} ↗</a>${c.wave?`<a class="tag orange" href="/energy-md/catalog/?wave=1&amp;sort=wave">Selecția inițială · nr. ${c.wave.rank}</a>`:''}${saveButton(c)}</div><div class="detail-grid"><div><section class="panel"><div class="evidence-block"><span class="label">PUBLICAT · ACTIVITATE</span><h2>Activitate și amploare</h2><p>${esc(c.facts)}</p>${sourceLinks(c.sources)}<p class="small-note" style="margin-top:12px">${esc(c.reviewStatus)}. Profilul diurn are un temei și o sursă separate mai jos.</p></div><div class="evidence-block"><span class="label inference">CONCLUZIE · MOTIVUL INCLUDERII</span><p>${esc(c.inference)}</p></div><div class="evidence-block"><span class="label unchecked">NEVERIFICAT · URMĂTOAREA ÎNTREBARE</span><p>${esc(c.question)}</p><button class="button secondary small" data-copy-question="${c.id}">Copiați întrebarea ⧉</button></div></section>${c.wave?`<section class="panel"><span class="label inference">SELECȚIA INIȚIALĂ · NR. ${c.wave.rank}</span><h3>Cum începeți discuția</h3><p>${esc(c.wave.question)}</p><button class="copy-small" data-copy-wave="${c.id}">Copiați prima întrebare ⧉</button></section>`:''}<section class="panel"><h2>Continuați cercetarea</h2><p>Verificați situația actuală, identificați unitatea de producție, clarificați datele financiare sau pregătiți întrebări pentru responsabilul de electricitate.</p><a class="button" href="/energy-md/research/?company=${c.id}">Creați o interogare pentru companie ↗</a></section></div><aside>${dayPanel(c)}<section class="panel"><span class="label">CONTACT PROFESIONAL</span><h2>Acces la persoana responsabilă</h2><p class="contact-number">${esc(con.phone)}</p><p class="contact-email">${esc(con.email)}</p><p>${esc(con.quality)}</p><div class="contact-route"><strong>Persoana de solicitat</strong><br>${esc(con.person)}</div><button class="button secondary small" data-copy-contact="${c.id}">Copiați contactele ⧉</button>${sourceLinks(con.sources)}<p class="small-note" style="margin-top:15px">Contactul nu a fost verificat telefonic. Nu au fost trimise mesaje.</p></section><section class="panel"><span class="label">AMPLOAREA AFACERII</span><h2>Venituri și personal</h2>${f?`<dl class="data-list"><div><dt>Venituri, ${f.year}</dt><dd class="big">${money(f.revenue)}</dd></div><div><dt>Angajați</dt><dd>${esc(f.employees)}</dd></div><div><dt>IDNO</dt><dd>${esc(f.idno)}</dd></div><div><dt>360 mii / venituri</dt><dd>${num(360000/f.revenue*100,3)}%</dd></div></dl><p class="small-note" style="margin-top:17px">${esc(f.sourceType)}. ${esc(f.limitation)}</p>${sourceLinks(f.sources)}<div class="note-strip">Raportul dintre pragul anual și venituri este un reper aritmetic. Ponderea reală a cheltuielilor pentru electricitate nu este cunoscută.</div>`:'<p>Aceste documente nu conțin o înregistrare financiară pentru companie. Aceasta nu înseamnă lipsa veniturilor.</p><a class="text-link" href="/energy-md/research/?company='+c.id+'&task=finance">Pregătiți căutarea financiară ↗</a>'}</section></aside></div>${notice()}</div>`;}
const tasks=[{id:'full',title:'Analiză completă a companiei',desc:'Statut, unități, producție, amploare, surse și date necunoscute.'},{id:'expand',title:'Extindeți lista companiilor',desc:'Identificați întreprinderi și organizații similare în afara bazei actuale.'},{id:'finance',title:'Verificați veniturile și persoana juridică',desc:'Anul raportării, IDNO, raport primar, personal și aria indicatorilor.'},{id:'contact',title:'Găsiți persoana responsabilă',desc:'Contact profesional public și acces la achiziții sau inginerul-șef.'},{id:'load',title:'Clarificați sarcina electrică',desc:'Procese, schimburi, sezonalitate, producție proprie și achiziții din rețea.'},{id:'interview',title:'Pregătiți întrebările pentru discuție',desc:'Calificare scurtă înainte de solicitarea facturilor și a contractului.'}];
function research(){return pageHead('O căutare bună începe cu o întrebare.','Alegeți compania sau sectorul, sarcina și limba căutării. Obțineți o interogare editabilă, pe care o puteți copia într-un motor de căutare sau într-un asistent AI.')+`<div class="content"><div class="research-grid"><section class="panel"><span class="label">01 / CONFIGURAȚI SARCINA</span><div class="research-options"><div class="field"><label for="research-company">Companie</label><select id="research-company"><option value="">Fără o companie anume</option>${[...DATA.companies].sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label for="research-sector">Sector</label><select id="research-sector"><option value="">Toate sectoarele</option>${DATA.sectors.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label for="research-task">Ce doriți să aflați</label><select id="research-task">${tasks.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}</select></div><div class="field"><label for="research-lang">Limba interogării și a răspunsului</label><select id="research-lang"><option value="ru">Rusă</option><option value="ro">Română</option><option value="both">Rusă și română</option></select></div><div class="field"><label for="research-sources">Limba surselor pentru căutare</label><select id="research-sources"><option value="both">Rusă și română</option><option value="ro">Română</option><option value="ru">Rusă</option><option value="all">Rusă, română și engleză</option></select></div><div class="field"><label for="research-extra">Condiție suplimentară</label><input id="research-extra" placeholder="De exemplu: Bălți, depozite frigorifice" maxlength="500"></div><button class="button" id="build-prompt">Generați interogarea ↗</button></div><p class="small-note" style="margin-top:18px">Interogarea se actualizează la alegerea condițiilor. Modificările manuale se păstrează până apăsați «Generați interogarea». Datele nu sunt trimise.</p></section><section class="panel"><div class="prompt-head"><div><span class="label">02 / COPIAȚI ȘI CONTINUAȚI</span><h2>Interogarea dvs.</h2></div><button class="button orange small" id="copy-prompt">Copiați ⧉</button></div><div class="field"><label for="prompt-text" class="small-note">Puteți edita textul înainte de copiere</label><textarea id="prompt-text" spellcheck="false"></textarea></div><p id="prompt-status" class="small-note" role="status" aria-live="polite"></p><div id="search-shortcuts" class="search-links"></div><p class="small-note">Linkurile deschid căutarea într-o filă nouă. Rezultatele nu sunt adăugate automat în bază.</p></section></div><div class="subsection"><div class="section-head"><h2>Șase sarcini de cercetare</h2><p>Șabloanele țin cont de compania sau sectorul selectat.</p></div><div class="template-grid">${tasks.map((t,i)=>`<button class="template" data-task="${t.id}"><span>0${i+1} / ȘABLON</span><strong>${t.title}</strong><p>${t.desc}</p><em>Aplicați interogării ↗</em></button>`).join('')}</div></div></div>`;}
function makePrompt(){
  const lang=$('#research-lang').value||UI_LANG;
  const ru=()=>composePromptRU(DATASETS.ru),ro=()=>composePromptRO(DATASETS.ro);
  return lang==='both'?ru()+'\n\n──────── ROMÂNĂ ────────\n\n'+ro():lang==='ro'?ro():ru();
}
function buildPrompt(){
  $('#prompt-text').value=makePrompt();
  $('#prompt-text').dataset.generated=$('#prompt-text').value;
  $('#prompt-text').lang=$('#research-lang').value==='both'?UI_LANG:$('#research-lang').value;
  $('#prompt-status').textContent='Interogarea este pregătită. O puteți edita și copia.';
  buildSearchLinks();
}
function buildSearchLinks(){
  const company=getCompany($('#research-company').value),id=$('#research-sector').value;
  const languages=$('#research-sources').value==='all'?['ru','ro','en']:$('#research-sources').value==='both'?['ru','ro']:[$('#research-sources').value];
  const terms={ru:['предприятия Молдовы','Молдова производство фабрика контакты','Молдова выручка финансовый отчёт'],ro:['întreprinderi Moldova','Moldova producere fabrică contacte','Moldova venituri raport financiar'],en:['Moldova companies','Moldova manufacturing factory contacts','Moldova revenue financial report']};
  $('#search-shortcuts').innerHTML=languages.map(lang=>{
    const term=company?.name||DATASETS[lang==='en'?'ro':lang].sectors.find(s=>s.id===id)?.name||terms[lang][0];
    const query=term+' '+terms[lang][1],financial=(company?.idno||company?.finance?.idno||term)+' '+terms[lang][2];
    return `<a target="_blank" rel="noopener noreferrer" href="https://www.google.com/search?q=${encodeURIComponent(query)}">Căutare activitate · ${lang.toUpperCase()} ↗</a><a target="_blank" rel="noopener noreferrer" href="https://www.google.com/search?q=${encodeURIComponent(financial)}">Căutare financiară · ${lang.toUpperCase()} ↗</a>`;
  }).join('');
}
function initResearch(){
  $('#research-company').value=params.get('company')||'';
  const c=getCompany($('#research-company').value);
  $('#research-sector').value=c?getSector(c.sector).id:(params.get('sector')||'');
  $('#research-task').value=params.get('task')||(c?'full':'expand');
  if(!$('#research-task').value)$('#research-task').value='full';
  $('#research-lang').value=UI_LANG;
  $('#research-sector').disabled=!!c;
  const change=()=>{
    const selected=getCompany($('#research-company').value);
    $('#research-sector').disabled=!!selected;
    if(selected)$('#research-sector').value=getSector(selected.sector).id;
    const edited=$('#prompt-text').value!==$('#prompt-text').dataset.generated;
    if(!edited)buildPrompt();
    else {$('#prompt-status').textContent='Setările s-au schimbat. Apăsați «Generați interogarea» pentru a înlocui textul editat.';buildSearchLinks();}
  };
  ['research-company','research-sector','research-task','research-lang','research-sources'].forEach(id=>$('#'+id).addEventListener('change',change));
  $('#research-extra').addEventListener('input',change);
  $('#build-prompt').addEventListener('click',()=>{buildPrompt();toast('Interogarea a fost generată conform condițiilor selectate.');});
  $('#copy-prompt').addEventListener('click',()=>copyText($('#prompt-text').value));
  buildPrompt();
}

function method(){return pageHead('De la indicii la un client confirmat.','Metodologia extinde căutarea și păstrează precizia. Includerea în catalog indică un motiv de verificare, nu o valoare stabilită a facturii.')+`<div class="content"><div class="method-grid"><section class="panel"><div class="number">01</div><span class="label">PUBLICAT</span><h3>Ce comunică sursa</h3><p>Proces, utilaje, dimensiunea fabricii, numărul camerelor, venituri sau personal. Linkul și anul sunt păstrate împreună cu informația. Datele agregatoarelor necesită verificare.</p></section><section class="panel"><div class="number">02</div><span class="label inference">CONCLUZIE</span><h3>De ce merită verificat</h3><p>Combinația dintre proces și amploare permite selectarea unui candidat. Prioritatea A, B sau S determină ordinea lucrului și nu măsoară consumul.</p></section><section class="panel"><div class="number">03</div><span class="label unchecked">NEVERIFICAT</span><h3>Ce trebuie să confirme clientul</h3><p>Facturi lunare, achiziții din rețea, furnizor, contract și disponibilitatea de schimbare. Fără aceste date nu se pot calcula sau promite economii.</p></section></div><div class="subsection detail-grid"><section class="panel"><span class="label">CRITERIU MONETAR</span><h2>30 000 × 12 = 360 000 MDL</h2><p>Echivalentul anual al pragului minim. Împărțirea a 360 000 MDL la veniturile anuale arată ce pondere a acestora este suficientă pentru atingerea pragului.</p><div class="note-strip">Acesta nu este un calcul al cheltuielilor reale. Pentru afacerile sezoniere, media anuală nu înlocuiește verificarea lunii minime și a celei obișnuite.</div><p>Pragul se aplică plătitorului juridic și unui set convenit de obiecte. Sumele cu TVA, fără TVA, kWh și perioadele se înregistrează separat.</p></section><section class="panel"><h2>Ce modifică prioritatea</h2><p><strong>Consolidează argumentul:</strong> program confirmat al schimbului diurn de producție, procese electrice în serie și o unitate activă.</p><p><strong>Necesită clarificare:</strong> schimburi de noapte, frig permanent, sezonalitate, cuptoare pe gaz, chirie, venituri din comerț și producție proprie de energie.</p><a class="text-link" href="/energy-md/sources/#reserve">Consultați înregistrările amânate ↗</a></section></div><div class="subsection"><h2>Cinci pași de calificare</h2><div class="table-wrap" tabindex="0" role="region" aria-label="Tabel; derulați pe orizontală"><table class="financial-table"><thead><tr><th>PAS</th><th>CE TREBUIE STABILIT</th><th>REZULTAT</th></tr></thead><tbody><tr><td>01 · Prag</td><td>Factura lunară obișnuită, minimă și maximă; TVA</td><td>Achiziții de la 30 000 MDL / lună</td></tr><tr><td>02 · Obiect</td><td>Persoană juridică, IDNO, unitate, contor, chirie</td><td>Obiectul ofertei este definit</td></tr><tr><td>03 · Profil</td><td>kWh lunar, schimburi, noapte, weekend, producție proprie</td><td>Achizițiile din rețea sunt clarificate</td></tr><tr><td>04 · Contract</td><td>Furnizor, componentele prețului, termene și condiții de modificare</td><td>Procedura de schimbare este cunoscută</td></tr><tr><td>05 · Calcul</td><td>Volum comparabil, plăți și condiții de furnizare</td><td>Economia este confirmată prin calcul</td></tr></tbody></table></div><div class="callout"><div><h3>Întrebări pregătite pentru pasul următor</h3><p>Alegeți compania pentru a include procesele sale în scenariul discuției.</p></div><a class="button" href="/energy-md/research/?task=interview">Pregătiți întrebările ↗</a></div></div></div>`;}
function sources(){const finances=DATA.companies.filter(c=>c.finance).sort((a,b)=>b.finance.revenue-a.finance.revenue);return pageHead('Surse, documente și limitele datelor.','Documentele inițiale sunt păstrate. Au fost cercetate suplimentar site-uri de producție, posturi vacante, UPM, registrul oficial ASP și datele lunare CNED. Verificare: 17.10.2026; datele extragerilor sunt indicate separat.')+`<div class="content"><div class="document-row"><div class="file-icon">XLSX</div><div><h3>Energy-Day.xlsx</h3><p>${DATA.companies.length} profiluri · profil diurn · registrul ASP · consum CNED</p></div><a class="button" href="/energy-md/files/Energy-Day.xlsx" download>Baza extinsă ↓</a></div><div class="document-row"><div class="file-icon">XLSX</div><div><h3>Energy-Industry.xlsx</h3><p>6 foi · 80 de candidați · contacte · venituri · selecție inițială · rezervă</p></div><a class="button secondary" href="/energy-md/files/Energy-Industry.xlsx" download>Descărcați Excel ↓</a></div><div class="document-row"><div class="file-icon" style="background:var(--accent);color:white">PDF</div><div><h3>Energy-Analysis.pdf</h3><p>9 pagini · concluzii ale studiului · logica selecției · limitări</p></div><a class="button secondary" href="/energy-md/files/Energy-Analysis.pdf" download>Descărcați raportul ↓</a></div><div class="note-strip"><strong>Ce confirmă documentele:</strong> existența a 80 de profiluri, 26 de sectoare, 25 de înregistrări financiare și 20 de candidați în selecția inițială. <strong>Ce nu este stabilit:</strong> cheltuielile reale peste prag, furnizorii actuali, disponibilitatea de schimbare și economiile posibile.</div><section class="subsection"><div class="section-head"><h2>Surse financiare</h2><p>4 înregistrări APP și 21 din agregatoare. Veniturile se referă la un an și o persoană juridică specifice.</p></div><div class="table-wrap" tabindex="0" role="region" aria-label="Tabel; derulați pe orizontală"><table class="financial-table"><thead><tr><th>COMPANIE</th><th>AN</th><th>VENITURI, MIL. MDL</th><th>SURSĂ</th></tr></thead><tbody>${finances.map(c=>`<tr><td><a href="${companyUrl(c)}">${esc(c.name)} ↗</a></td><td>${c.finance.year}</td><td>${num(c.finance.revenue/1000000,2)}</td><td>${sourceLinks(c.finance.sources)}</td></tr>`).join('')}</tbody></table></div><p class="small-note" style="margin-top:15px">Sandriliona: anul 2024. Purcari: venituri rotunjite ale persoanei juridice locale. Barza Albă: conversie din mii MDL. Precizările complete sunt disponibile în profilurile companiilor.</p></section><section class="subsection" id="reserve"><div class="section-head"><h2>9 înregistrări pentru verificare suplimentară</h2><p>Rezerva nu face parte din catalogul principal. Motivele și acțiunile următoare sunt păstrate din Excel.</p></div><div class="reserve-grid">${DATA.reserve.map(r=>`<details><summary>${esc(r.name)} <span class="muted">/ ${esc(r.sector)}</span></summary><p><strong>Publicat:</strong> ${esc(r.facts)}</p><p><strong>Motivul amânării:</strong> ${esc(r.reason)}</p><p><strong>Acțiunea următoare:</strong> ${esc(r.action)}</p>${sourceLinks(r.sources)}<button class="copy-small" data-copy-reserve="${r.id}">Copiați sarcina ⧉</button></details>`).join('')}</div></section></div>`;}
function bindGlobal(){document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.save;if(id){const old=new Set(saved);saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('energy-md-saved',JSON.stringify([...saved]));}catch{saved=old;toast('Browserul nu a permis salvarea favoritelor.');return;}if(route==='/catalog')filterCatalog();else $$(`[data-save="${id}"]`).forEach(el=>{el.outerHTML=saveButton(getCompany(id));});toast(saved.has(id)?'Compania a fost adăugată la favoritele acestui browser.':'Compania a fost eliminată din favorite.');}if(b.dataset.copyQuestion){const c=getCompany(b.dataset.copyQuestion);await copyText(c.name+'\n'+c.question);}if(b.dataset.copyWave){const c=getCompany(b.dataset.copyWave);await copyText(c.name+'\n'+c.wave.question);}if(b.dataset.copyContact){const c=getCompany(b.dataset.copyContact);await copyText([c.name,c.contact.phone,c.contact.email,'Destinație: '+c.contact.quality,'Persoana de solicitat: '+c.contact.person,'Sursă: '+c.contact.sources,'Contactul nu a fost verificat telefonic.'].join('\n'));}if(b.dataset.copyReserve){const r=DATA.reserve.find(r=>r.id===b.dataset.copyReserve);await copyText(r.name+'\nVerificați: '+r.action+'\nMotiv: '+r.reason+'\nSursă: '+r.sources);}if(b.dataset.task){$('#research-task').value=b.dataset.task;buildPrompt();$('#prompt-text').scrollIntoView({behavior:'smooth',block:'center'});toast('Șablonul a fost aplicat obiectului selectat.');}if(b.hasAttribute('data-reset'))$('#reset-filters')?.click();});}
async function start(){try{const responses=await Promise.all([fetch('/energy-md/data.json'),fetch('/energy-md/data.ro.json')]);if(responses.some(r=>!r.ok))throw Error('data');const datasets=await Promise.all(responses.map(r=>r.json()));DATASETS={ru:datasets[0],ro:datasets[1]};DATA=DATASETS[UI_LANG];loadSaved();let markup;if(route==='/')markup=home()+universeIntro();else if(route==='/registry')markup=directoryPageHTML('registry');else if(route==='/public-energy')markup=directoryPageHTML('public');else if(route==='/catalog')markup=catalog();else if(route==='/sectors')markup=sectors();else if(route==='/wave')markup=wave();else if(route==='/research')markup=research();else if(route==='/method')markup=method();else if(route==='/sources')markup=sources();else if(route.startsWith('/company/')){const c=getCompany(route.split('/')[2]);if(c)markup=companyPage(c);}else if(route.startsWith('/sector/')){const s=DATA.sectors.find(s=>s.id===route.split('/')[2]);if(s)markup=sectorPage(s);}if(!markup)markup=pageHead('Pagina nu a fost găsită','Deschideți catalogul sau alegeți un sector.')+'<div class="content"><a class="button" href="/energy-md/catalog/">Deschideți companiile ↗</a></div>';$('#main').innerHTML=markup;$$('.site-header nav a').forEach(a=>{const path=localPath(new URL(a.href).pathname).replace(/\/$/,'');if(route===path||(path==='/catalog'&&route.startsWith('/company/'))||(path==='/sectors'&&route.startsWith('/sector/'))){a.classList.add('active');a.setAttribute('aria-current','page');}});if(route==='/catalog')initCatalog();if(route==='/research')initResearch();if(route==='/registry')await initDirectory('registry');if(route==='/public-energy')await initDirectory('public');bindGlobal();window.energyReady?.();document.title=($('#main h1')?.innerText||'Energy MD').replace(/\s+/g,' ')+' · Energy MD';}catch(error){$('#main').innerHTML='<div class="content" style="padding-top:70px"><h1>Datele nu au putut fi încărcate.</h1><p>Reîncărcați pagina sau descărcați documentele inițiale.</p><a class="button" href="/energy-md/files/Energy-Industry.xlsx">Descărcați Excel ↓</a></div>';console.error(error);}}
const dayOrder={factory:0,shift:1,general:2,hypothesis:3,unknown:4,mixed:5};
const dayCandidates=()=>DATA.companies.filter(c=>['factory','shift','general'].includes(c.day.kind)).sort((a,b)=>dayOrder[a.day.kind]-dayOrder[b.day.kind]);
function dayBadge(c){return `<span class="tag ${['factory','shift'].includes(c.day.kind)?'day-strong':''}">${esc(c.day.label)}</span>`;}
function dayPanel(c){return `<section class="panel"><span class="label">PROFIL DIURN</span><h2>${esc(c.day.label)}</h2>${c.day.hours?`<p class="day-hours">${esc(c.day.hours)}</p>`:''}<p>${esc(c.day.evidence)}</p>${sourceLinks(c.day.sources)}<p class="small-note">${esc(c.day.limitation)}</p><dl class="data-list"><div><dt>Ponderea kWh diurni din rețea</dt><dd>Nestabilită</dd></div><div><dt>Cheltuieli de la 30 000 MDL/lună</dt><dd>Neconfirmat</dd></div><div><dt>Producție proprie de energie</dt><dd>${esc(c.generationText||'Necesită verificare')}</dd></div></dl><p class="small-note">Nu confundați consumul cu programul biroului. Calculați achizițiile din rețea după producția proprie.</p></section>${c.registryMatch?`<section class="panel"><span class="label">CORELARE CU ASP</span><p><strong>${esc(c.registryMatch.legalName)}</strong></p><p>IDNO ${esc(c.registryMatch.idno)}</p><p>${esc(c.registryMatch.registeredAddress)}</p><p class="small-note">${esc(c.registryMatch.note)}</p>${sourceLinks(c.registryMatch.source)}</section>`:''}`;}
function dayWave(){const strong=dayCandidates().filter(c=>c.day.kind!=='general'),general=dayCandidates().filter(c=>c.day.kind==='general');return pageHead('Prioritate diurnă','Începem cu programele publicate ale fabricilor și schimburilor de producție. Pragul monetar și ponderea diurnă reală se verifică separat.')+`<div class="content"><div class="results-bar"><span>${strong.length} programe de fabrici / schimburi · ${general.length} programe generale</span><a class="button secondary small" href="/energy-md/catalog/?day=signal&sort=day">Filtre și CSV ↓</a></div><h2>Fabrică sau schimb de producție</h2><div class="company-grid">${strong.map(c=>companyCard(c)).join('')}</div><div class="subsection"><h2>Program diurn general</h2><p>Acesta este un indiciu mai slab: orele de primire și vânzare pot diferi de funcționarea utilajelor.</p><div class="company-grid">${general.map(c=>companyCard(c)).join('')}</div></div>${notice()}<details class="panel"><summary>Selecția inițială din studiu</summary><p>Cei 20 de candidați inițiali sunt păstrați, dar nu reprezintă o recomandare diurnă. Frigul, panificația și procesele continue necesită verificarea separată a sarcinii nocturne.</p><a class="text-link" href="/energy-md/catalog/?wave=1&sort=wave">Deschideți selecția inițială ↗</a></details></div>`;}
function universeIntro(){return `<section class="section"><div class="section-head"><div><div class="eyebrow">Surse deschise / extinderea acoperirii</div><h2>De la zeci de profiluri<br>la o căutare sistematică</h2></div></div><div class="detail-grid"><article class="panel"><span class="label">ASP · 12.10.2026</span><h3>${num(DATA.registryMeta.count)} înregistrări</h3><p>Persoane juridice cu activitate de producție declarată. Denumire, IDNO, regiune de înregistrare și CAEM. Activitatea efectivă, regimul diurn și factura nu sunt încă confirmate.</p><a class="button secondary" href="/energy-md/registry/">Căutați în registru ↗</a></article><article class="panel"><span class="label">CNED · IANUARIE–APRILIE 2026</span><h3>${num(DATA.publicMeta.largeRows)} rânduri de la 10 000 kWh/lună</h3><p>Volume lunare publicate ale organizațiilor. Rândurile nu reprezintă organizații unice. Acesta este un volum fizic, nu o confirmare a pragului de 30 000 MDL sau a ponderii diurne.</p><a class="button secondary" href="/energy-md/public-energy/">Analizați consumul ↗</a></article></div></section>`;}
let REGISTRY=null, PUBLIC_ENERGY=null, directoryRows=[],directoryPage=0;
const publicGroups={education:'Educație',medical:'Medicină',municipal:'Administrație / municipale',other:'Alte organizații'};
function directoryPageHTML(type){const reg=type==='registry';return pageHead(reg?'Registrul extins ASP':'Consum publicat CNED',reg?'Activitățile declarate ajută la identificarea întreprinderilor pentru cercetare. Registrul nu confirmă funcționarea fabricii, veniturile sau cheltuielile sale.':'kWh lunari reali din tabelul public. Ponderea diurnă, plătitorul contractual și cheltuielile în lei nu sunt stabilite separat.')+`<div class="content"><div class="note-strip">${esc(reg?DATA.registryMeta.note:DATA.publicMeta.note)}</div><div class="filters directory-filters"><div class="field"><label for="directory-q">Denumire, ${reg?'IDNO, adresă sau activitate':'raion sau localitate'}</label><input id="directory-q" type="search" placeholder="De exemplu: mobilă, tipar, Bălți…"></div><div class="field"><label for="directory-group">${reg?'Sector de producție':'Tipul organizației · după denumire'}</label><select id="directory-group"><option value="">Toate</option>${!reg?Object.entries(publicGroups).map(([k,v])=>`<option value="${k}">${v}</option>`).join(''):''}</select></div><div class="field"><label for="directory-region">${reg?'Regiunea de înregistrare':'Raion'}</label><select id="directory-region"><option value="">Toate</option></select></div>${!reg?'<div class="field"><label for="directory-min">Media, de la kWh/lună</label><input id="directory-min" type="number" min="0" value="10000" step="1000"></div>':''}<div class="filter-bottom"><button class="button secondary small" id="directory-export">Exportați selecția CSV ↓</button><a href="/energy-md/files/Energy-Day.xlsx" class="text-link" download>Baza completă Excel ↓</a></div></div><div class="results-bar"><span id="directory-count" aria-live="polite">Se încarcă datele…</span><div class="pagination"><button class="button secondary small" id="directory-prev" aria-label="Pagina precedentă">←</button><span id="directory-page"></span><button class="button secondary small" id="directory-next" aria-label="Pagina următoare">→</button></div></div><p class="table-hint">Tabelul poate fi derulat pe orizontală ↔</p><div id="directory-table" class="table-wrap" tabindex="0" role="region" aria-label="Tabel; derulați pe orizontală"></div><div class="note-strip">${reg?'Adresa este cea de înregistrare. O activitate poate fi secundară. Lipsa datei de lichidare nu înseamnă că producția funcționează.':'Media este calculată pe lunile completate din ianuarie–aprilie 2026, inclusiv valorile zero. Câmpurile goale nu sunt înlocuite cu zero. Rândurile cu aceeași denumire nu sunt însumate. Selecția de la 10 000 kWh este un filtru de cercetare, nu echivalentul pragului monetar.'}</div><p>${sourceLinks(reg?DATA.registryMeta.source:DATA.publicMeta.source)}</p></div>`;}
async function initDirectory(type){const reg=type==='registry';try{const res=await fetch(reg?'/energy-md/registry.json':'/energy-md/public-energy.json');if(!res.ok)throw Error('fetch');const data=await res.json();if(reg)REGISTRY=data;else PUBLIC_ENERGY=data;const regions=[...new Set(data.rows.map(r=>reg?r[3]:r.district))].filter(Boolean).sort((a,b)=>a.localeCompare(b,'ro'));$('#directory-region').innerHTML='<option value="">Toate</option>'+regions.map(x=>`<option value="${esc(x)}">${esc(x)}</option>`).join('');if(reg)$('#directory-group').innerHTML='<option value="">Toate activitățile</option>'+data.activities.map((a,i)=>`<option value="${i}">CAEM ${esc(a.code)} · rev.${a.version} · ${esc(a.description)}</option>`).join('');for(const id of ['directory-q','directory-group','directory-region',...(!reg?['directory-min']:[])])$('#'+id).addEventListener(id==='directory-q'||id==='directory-min'?'input':'change',()=>{directoryPage=0;filterDirectory(type);});$('#directory-prev').addEventListener('click',()=>{directoryPage--;renderDirectory(type);});$('#directory-next').addEventListener('click',()=>{directoryPage++;renderDirectory(type);});$('#directory-export').addEventListener('click',()=>exportDirectory(type));filterDirectory(type);}catch{$('#directory-count').textContent='Tabelul nu a putut fi încărcat. Reîncărcați pagina sau descărcați Excel.';}}
function directoryFilter(type,q='',group='',region='',minimum=0){q=searchKey(q.trim());if(type==='registry')return REGISTRY.rows.filter(r=>(!group||r[4].includes(Number(group)))&&(!region||r[3]===region)&&(!q||searchKey([r[0],r[1],r[2],...r[4].map(i=>REGISTRY.activities[i].description)].join(' ')).includes(q)));return PUBLIC_ENERGY.rows.filter(r=>(!group||r.group===group)&&(!region||r.district===region)&&r.average>=minimum&&(!q||searchKey([r.name,r.district,r.locality].join(' ')).includes(q))).sort((a,b)=>b.average-a.average);}
function filterDirectory(type){directoryRows=directoryFilter(type,$('#directory-q').value,$('#directory-group').value,$('#directory-region').value,Math.max(0,Number($('#directory-min')?.value)||0));renderDirectory(type);}
function renderDirectory(type){const reg=type==='registry';const pages=Math.max(1,Math.ceil(directoryRows.length/30));directoryPage=Math.max(0,Math.min(directoryPage,pages-1));$('#directory-prev').disabled=directoryPage===0;$('#directory-next').disabled=directoryPage>=pages-1;$('#directory-export').disabled=!directoryRows.length;$('#directory-page').textContent=`${directoryPage+1} / ${pages}`;$('#directory-count').textContent=`${num(directoryRows.length)} rânduri · ${reg?'starea producției nu este verificată':'kWh; nu valoarea plății'}`;const heads=reg?['PERSOANĂ JURIDICĂ / IDNO','ADRESA DE ÎNREGISTRARE','PRODUCȚIE DECLARATĂ','CONTINUAȚI']:['ORGANIZAȚIE / RÂND XLSX','RAION','IAN','FEB','MAR','APR','MEDIA','LIMITĂRI'];const body=directoryRows.slice(directoryPage*30,directoryPage*30+30).map(r=>reg?`<tr><td><strong>${esc(r[1])}</strong><br>${r[0]}</td><td>${esc(r[2])}</td><td>${r[4].map(i=>{const a=REGISTRY.activities[i];return esc(a.code+' (rev.'+a.version+') '+a.description);}).join('<br>')}</td><td><a class="text-link" target="_blank" rel="noopener noreferrer" href="https://www.google.com/search?q=${encodeURIComponent(r[0]+' '+r[1]+' producere fabrica program de lucru contacte')}">Verificați ↗</a><br><button class="copy-small" data-directory-copy="${r[0]}">Copiați sarcina</button></td></tr>`:`<tr><td><strong>${esc(r.name)}</strong><br>Foaia 2026 · rândul ${r.sourceRow}</td><td>${esc(r.district)}<br>${esc(r.locality)}</td>${r.months.map(v=>`<td>${v==null?'—':num(v)}</td>`).join('')}<td><strong>${num(r.average)}</strong></td><td>${esc(publicGroups[r.group])}<br>${r.duplicateName?'Denumire repetată. ':''}${r.group==='municipal'?'Poate include iluminat nocturn.':r.group==='education'?'Sunt posibile cămine și consum nocturn de fond.':'Profilul diurn nu este stabilit.'}</td></tr>`).join('');$('#directory-table').innerHTML=`<table class="financial-table directory-table"><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${body||`<tr><td colspan="${heads.length}">Nu există rezultate. Modificați condițiile.</td></tr>`}</tbody></table>`;$$('[data-directory-copy]').forEach(b=>b.addEventListener('click',()=>{const r=REGISTRY.rows.find(r=>r[0]===b.dataset.directoryCopy);copyText(`Verifică întreprinderea ${r[1]}, IDNO ${r[0]}, Republica Moldova. Sursa identificării: ASP din 12.10.2026, ${REGISTRY.source}. Stabilește dacă producția funcționează, adresa atelierului, utilajele, veniturile cu an și sursă, contactul profesional public, schimburile de producție, consumul nocturn de fond și producția proprie. Prioritate principală: achiziții de electricitate din rețea predominant ziua, de la 30 000 MDL pe lună. Adresa de înregistrare ${r[2]} nu trebuie considerată automat adresa fabricii. Caută facturi publicate, rapoarte, achiziții și kWh pe intervale; nu inventa plăți bancare. Separă faptele, concluziile și necunoscutele; oferă linkuri și date. Nu trimite mesaje companiei.`);}));}
function downloadCSV(rows,name){const cell=v=>{let s=String(v??'');if(/^[=+\-@]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};const blob=new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8;'});const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),5000);}
function exportDirectory(type){if(type==='registry')downloadCSV([['IDNO','Persoană juridică','Adresa de înregistrare','Regiune','Activități de producție','Stare','Sursă'],...directoryRows.map(r=>[r[0],r[1],r[2],r[3],r[4].map(i=>{const a=REGISTRY.activities[i];return a.code+' rev.'+a.version+' '+a.description;}).join('; '),'Activitate declarată; funcționarea, profilul diurn și cheltuielile nu sunt verificate',REGISTRY.source])],'Energy-ASP-selection.csv');else downloadCSV([['Rând XLSX 2026','Organizație','Raion','Localitate','Ian kWh','Feb kWh','Mar kWh','Apr kWh','Media kWh','Luni completate','Denumire repetată','Sursă','Limitare'],...directoryRows.map(r=>[r.sourceRow,r.name,r.district,r.locality,...r.months,r.average,r.reportedMonths,r.duplicateName?'Da':'Nu',PUBLIC_ENERGY.source,'Profilul diurn și cheltuielile MDL sunt necunoscute; nu însumați rândurile'])],'Energy-CNED-selection.csv');}

start();
